export type RuntimeMetrics = {
  turnsTotal: number;
  invalidOutputCount: number;
  actionAppliedCount: number;
  actionRejectedCount: number;
  queuedActions: number;
};

// ... existing types ...

export type ServerMessage =
  | {
      version: Version;
      type: "session.state";
      // ... existing payload ...
    }
  // ... other existing message types ...
  | {
      version: Version;
      type: "runtime.metrics";
      payload: RuntimeMetrics;
    };

// ... existing schemas ...

// Add the schema for the new message type to the discriminated union
const clientMessageSchema = z.discriminatedUnion("type", [
  // ... existing client message schemas ...
]);

// Note: Server messages are not validated by a schema in this file currently, 
// but the type definition above ensures TypeScript safety for the client.
```

### 2. Runtime Server Implementation
**File**: `apps/game-runtime/src/runtime/GameRuntimeServer.ts`

Update `sendSessionState` to include metrics and add a new `sendMetrics` method called during the tick loop.

```typescript
// apps/game-runtime/src/runtime/GameRuntimeServer.ts

// ... existing imports ...
import type { RuntimeMetrics } from "./types"; // Ensure this import exists or use the protocol type if moved

// ... inside GameRuntimeServer class ...

  private sendSessionState(): void {
    this.emitMessage({
      version: PROTOCOL_VERSION,
      type: "session.state",
      payload: {
        phase: this.phase,
        paused: this.paused,
        preparedSeed: this.preparedSeed,
        threadIds: this.threadIds,
        connected: this.connected,
        runtime: {
          model: this.turnModel,
          effort: this.turnEffort,
          tickMs: runtimeConfig.tickMs,
          schedulerMs: runtimeConfig.schedulerMs,
          maxQueuedActionsBeforeTurn: runtimeConfig.maxQueuedActionsBeforeTurn,
          availableModels: this.availableModels
        }
      }
    });
    // Emit current metrics immediately when state is sent
    this.sendMetrics();
  }

  private sendMetrics(): void {
    const metrics = this.metrics.snapshot();
    this.emitMessage({
      version: PROTOCOL_VERSION,
      type: "runtime.metrics",
      payload: metrics
    });
  }

  private tick(): void {
    if (!this.simulation || this.phase !== "running") {
      return;
    }

    if (this.paused) {
      this.metrics.setQueueDepth(this.totalQueuedActions());
      this.sendMetrics(); // Send metrics even when paused to update queue depth
      return;
    }

    this.simulation.tick();

    const agents = this.simulation.getState().agents.map((agent) => agent.id).sort();
    for (const agentId of agents) {
      const queue = this.actionQueueByAgent.get(agentId);
      const nextAction = queue?.shift();
      if (!nextAction) {
        continue;
      }
      const result = this.simulation.applyAction(agentId, nextAction);
      if (result.result === "applied") {
        this.metrics.onActionApplied();
      } else {
        this.metrics.onActionRejected();
      }
      this.emitMessage({
        version: PROTOCOL_VERSION,
        type: "agent.action",
        payload: {
          agentId,
          action: result.action,
          result: result.result,
          ...(result.reason ? { reason: result.reason } : {})
        }
      });
      void this.logReplay("action.applied", {
        agentId,
        action: result.action,
        result: result.result,
        reason: result.reason ?? null
      });
    }

    this.metrics.setQueueDepth(this.totalQueuedActions());
    this.sendWorldSnapshot();
    this.sendMetrics(); // Send metrics after tick updates
  }

// ... rest of the class ...
```

### 3. Client HUD Update
**File**: `apps/game-client/src/App.tsx`

Add state for metrics, handle the new message type, and display the data in the HUD.

